package com.andye.warmod.radar.display;import com.andye.warmod.block.entity.RadarDisplayPanelBlockEntity;import java.util.*;import net.minecraft.server.level.ServerLevel;
public final class RadarDisplayManager{private RadarDisplayManager(){}public static RadarDisplayStructure rebuild(ServerLevel level,net.minecraft.core.BlockPos panel){RadarDisplayStructure s=RadarDisplayStructure.resolve(level,panel);RadarDisplayLink common=null;for(var p:s.panels())if(level.getBlockEntity(p)instanceof RadarDisplayPanelBlockEntity be&&be.link()!=null){common=be.link();break;}UUID id=s.valid()?UUID.nameUUIDFromBytes((level.dimension().identifier()+":"+s.controller()).getBytes(java.nio.charset.StandardCharsets.UTF_8)):null;for(var p:s.panels())if(level.getBlockEntity(p)instanceof RadarDisplayPanelBlockEntity be)be.configure(id,s.controller(),s.size(),s.valid(),common);return s;}}
